/* ================================================
   30. RESPONSIVE DESIGN
   ================================================ */
@media (max-width: 1024px) {
    .stats-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .sidebar {
        width: 70px;
        padding: 15px 10px;
    }

    .sidebar-logo h2,
    .sidebar-logo p,
    .sidebar-menu a span,
    .sidebar-footer p,
    .menu-category small span {
        display: none;
    }

    .sidebar-logo i {
        font-size: 28px;
    }

    .sidebar-menu {
        padding: 0;
    }

    .sidebar-menu a {
        justify-content: center;
        padding: 15px;
    }

    .sidebar-menu i {
        margin: 0;
        font-size: 18px;
    }

    .menu-category {
        text-align: center;
        padding-left: 0;
    }

    .main-content {
        margin-left: 70px;
    }

    .header {
        flex-direction: column;
        gap: 15px;
        text-align: center;
    }

    .header-user {
        width: 100%;
        justify-content: center;
    }

    .dashboard-cards {
        grid-template-columns: 1fr;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

    .filter-grid {
        grid-template-columns: 1fr;
    }

    .stats-grid {
        grid-template-columns: 1fr;
    }

    .notification-dropdown {
        width: 280px;
        right: -70px;
    }
}

@media (max-width: 480px) {
    .profile-header h1 {
        font-size: 22px;
    }

    .card .card-value {
        font-size: 26px;
    }

    .modal-content {
        margin: 10% auto;
        padding: 20px;
        width: 95%;
    }

    .btn {
        padding: 8px 16px;
    }

    .table-container {
        padding: 15px;
    }

    th, td {
        padding: 10px;
        font-size: 13px;
    }
}

/* ================================================
   31. PRINT STYLES
   ================================================ */
@media print {
    .sidebar,
    .header,
    .btn,
    .search-box,
    .modal,
    .pagination,
    .sidebar-footer,
    .action-buttons,
    .pop-icon,
    .notification-wrapper {
        display: none !important;
    }

    .main-content {
        margin-left: 0;
        padding: 0;
    }

    .table-container {
        box-shadow: none;
        border: 1px solid #ddd;
        page-break-inside: avoid;
    }

    body {
        background: white;
    }
}

